# ── helpers, below the marker so the library above stays untouched ─────────

# verdict KEY "Question" records pass / fail / skip plus a free-text note.
# Both land in ENV_FILE, so a re-run offers what you answered last time and
# you can stop half way without losing the morning.
verdict() {
  local key="$1" label="$2" v
  while :; do
    ask "$key" "  ${label} [p]ass / [f]ail / [s]kip:"
    v="$(printf '%s' "${!key}" | tr '[:upper:]' '[:lower:]')"
    case "$v" in
      p|pass) v="pass"; break ;;
      f|fail) v="fail"; break ;;
      s|skip) v="skip"; break ;;
      *) warn "gõ p, f hoặc s" ;;
    esac
  done
  write_env "$key" "$v"
  ask "${key}_NOTE" "  Ghi chú (Enter để bỏ qua):"
  local note_var="${key}_NOTE"
  write_env "$note_var" "${!note_var}"
  if [[ "$v" == "fail" ]]; then
    warn "FAIL: mở issue mới, dán đúng dòng quan sát được. Đừng sửa tại chỗ."
  fi
}

# open_doc FILE opens a workspace file in the running VS Code window.
open_doc() {
  local f="$WS/$1"
  if command -v code >/dev/null 2>&1; then
    printf '  %s↗ mở%s %s\n' "$GREEN" "$RESET" "$1"
    code -r "$f" >/dev/null 2>&1 || warn "không mở được $f"
  else
    warn "không có lệnh 'code'; mở tay: $f"
  fi
}

