stage "X2: Các menu TRÔNG như thế nào"
note "Floor khẳng định menu hiện ra và đúng số mục. Nó không nói gì về đẹp xấu."
open_doc "test.md"
step "Xem lần lượt: menu slash (gõ /), bubble menu, link popover,"
step "menu chuột phải bảng, lightbox (double-click ảnh)."
step "Ở CẢ theme sáng và tối."
say "Soát: canh lề, khoảng cách, màu chữ trên nền, trạng thái hover."
verdict X2 "X2"

# ── Kết quả ───────────────────────────────────────────────────────────────

_clear
{
  printf '# Kết quả bản kiểm tay\n\n'
  printf 'Ngày: %s  ·  Phiên bản: %s  ·  VS Code: %s\n\n' \
    "$(date +%Y-%m-%d)" \
    "$(node -p "require('$REPO_ROOT/package.json').version" 2>/dev/null || echo '?')" \
    "$(code --version 2>/dev/null | head -1 || echo '?')"
  printf 'Sinh bởi `scripts/manual-checks.sh`. Tiêu chí và lý do từng mục nằm ở\n'
  printf '`docs/manual-checks.md`.\n\n'
  printf '| Mục | Kết quả | Ghi chú |\n| --- | --- | --- |\n'
  for k in A1B A2 A3B B1 B2 C1 C2 C3 C4B E1B F1 G1 X1 X2; do
    v=$(grep -E "^${k}=" "$ENV_FILE" | tail -n1 | cut -d= -f2- || true)
    n=$(grep -E "^${k}_NOTE=" "$ENV_FILE" | tail -n1 | cut -d= -f2- || true)
    printf '| %s | %s | %s |\n' "$k" "${v:-chưa chạy}" "${n:-}"
  done
  printf '\nMục nào `fail` thì mở issue mới, dán đúng dòng quan sát được.\n'
  printf 'Mục nào `skip` thì vẫn là nợ, không phải là xong.\n'
} > "$REPORT"

finish
note "báo cáo: $REPORT"
note "kết quả thô (chạy lại sẽ nhớ): $ENV_FILE"
printf '\n'
pass_n=$(grep -cE '^[A-Z0-9_]+=pass$' "$ENV_FILE" 2>/dev/null || true)
fail_n=$(grep -cE '^[A-Z0-9_]+=fail$' "$ENV_FILE" 2>/dev/null || true)
skip_n=$(grep -cE '^[A-Z0-9_]+=skip$' "$ENV_FILE" 2>/dev/null || true)
printf '  %spass %s%s  ·  %sfail %s%s  ·  %sskip %s%s\n\n' \
  "$GREEN" "$pass_n" "$RESET" "$RED" "$fail_n" "$RESET" "$YELLOW" "$skip_n" "$RESET"
